function customerMatchesQuery(customer, query) {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  const qDigits = q.replace(/\D/g, "");
  const fieldsMatch = [customer.name, customer.address, customer.office, customer.carrier, customer.policyNumber, customer.email]
    .filter(Boolean)
    .some((f) => f.toLowerCase().includes(q));
  const phoneMatch = qDigits.length >= 3 && customer.phone.replace(/\D/g, "").includes(qDigits);
  const driverMatch = (customer.drivers || []).some((d) => d.name.toLowerCase().includes(q) || d.relation.toLowerCase().includes(q));
  return fieldsMatch || phoneMatch || driverMatch;
}

