const TODAY = new Date();

function formatTodayDate() {
  const mm = String(TODAY.getMonth() + 1).padStart(2, "0");
  const dd = String(TODAY.getDate()).padStart(2, "0");
  return `${mm}/${dd}/${TODAY.getFullYear()}`;
}

function isWithinLastNDays(dateStr, n) {
  const parsed = parseQuoteDate(dateStr);
  const diffDays = (TODAY - parsed) / (1000 * 60 * 60 * 24);
  return diffDays >= 0 && diffDays <= n;
}

function parseQuoteDate(dateStr) {
  if (!dateStr || dateStr === "Today") return TODAY;
  const parts = dateStr.split("/").map(Number);
  if (parts.length !== 3 || parts.some(isNaN)) return new Date(0);
  const [month, day, year] = parts;
  return new Date(year, month - 1, day);
}

function sortByDate(list, order) {
  const sorted = [...list].sort((a, b) => parseQuoteDate(a.dateQuoted) - parseQuoteDate(b.dateQuoted));
  return order === "asc" ? sorted : sorted.reverse();
}

function findCustomerForDriver(customersList, driverName) {
  return customersList.find(
    (c) => c.name === driverName || (c.drivers || []).some((d) => d.name === driverName)
  );
}

