const blankVehicle = () => ({ vin: "", year: "", make: "", model: "", coverage: "Liability Only" });

async function decodeVin(vin) {
  const cleaned = vin.trim().toUpperCase();
  if (cleaned.length !== 17) return null;
  try {
    const res = await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/decodevin/${cleaned}?format=json`);
    if (!res.ok) return null;
    const data = await res.json();
    const results = data.Results || [];
    const getValue = (variable) => {
      const row = results.find((r) => r.Variable === variable);
      return row && row.Value && row.Value !== "Not Applicable" ? row.Value : "";
    };
    const year = getValue("Model Year");
    const make = getValue("Make");
    const model = getValue("Model");
    if (!year && !make && !model) return null;
    return {
      year,
      make: make ? toTitleCase(make) : "",
      model: model ? toTitleCase(model) : "",
    };
  } catch (err) {
    console.error("VIN decode failed:", err.message);
    return null;
  }
}

function AdditionalInfoSection({
  lockable = false,
  startLocked = false,
  onSaveDetails,
  initialDriverName = "",
  initialDrivers = null,
  initialVehicles = null,
  initialPolicyAmount = "",
  initialDownPayment = "",
  showPayment = true,
  primaryPhone = "",
  onPrimaryPhoneChange,
}) {
  const startsLocked = lockable && startLocked;
  const useSeedSample = startsLocked && !initialDrivers;
  const [isEditing, setIsEditing] = useState(!startsLocked);
  const [drivers, setDrivers] = useState(
    useSeedSample
      ? [{ firstName: "Maria", lastName: "Rodriguez", dob: "04/12/1985", idNumber: "TX-40218855", sex: "Female", maritalStatus: "Married", relation: "Self", status: "Included", phone: "" }]
      : initialDrivers && initialDrivers.length
      ? initialDrivers.map((d, i) => (i === 0 && !d.phone && primaryPhone ? { ...d, phone: primaryPhone } : d))
      : [{ ...blankDriver(), firstName: initialDriverName.split(" ")[0] || "", lastName: initialDriverName.split(" ").slice(1).join(" "), phone: primaryPhone }]
  );
  const [vehicles, setVehicles] = useState(
    useSeedSample
      ? [{ vin: "1HGCM82633A004352", year: "2003", make: "Honda", model: "Accord" }]
      : initialVehicles && initialVehicles.length
      ? initialVehicles
      : [blankVehicle()]
  );
  const [policyAmount, setPolicyAmount] = useState(useSeedSample ? "142.00" : initialPolicyAmount);
  const [downPayment, setDownPayment] = useState(useSeedSample ? "150.00" : initialDownPayment);
  const [archivedDrivers, setArchivedDrivers] = useState([]);
  const [archivedVehicles, setArchivedVehicles] = useState([]);
  const [showArchivedDrivers, setShowArchivedDrivers] = useState(false);
  const [showArchivedVehicles, setShowArchivedVehicles] = useState(false);
  const [validationError, setValidationError] = useState("");

  const updateDriver = (i, field, value) => {
    let v = value;
    if (field === "firstName" || field === "lastName") v = toTitleCase(v);
    setDrivers((prev) => prev.map((d, idx) => (idx === i ? { ...d, [field]: v } : d)));
    if (i === 0 && field === "phone" && onPrimaryPhoneChange) onPrimaryPhoneChange(v);
  };

  const addDriver = () => setDrivers((prev) => [...prev, blankDriver()]);
  const removeDriver = (i) => {
    setArchivedDrivers((arch) => [...arch, drivers[i]]);
    setDrivers((prev) => prev.filter((_, idx) => idx !== i));
  };
  const restoreDriver = (i) => {
    setDrivers((prev) => [...prev, archivedDrivers[i]]);
    setArchivedDrivers((prev) => prev.filter((_, idx) => idx !== i));
  };

  const updateVehicleField = (i, field, value) => {
    let v = value;
    if (field === "make" || field === "model") v = toTitleCase(v);
    setVehicles((prev) => prev.map((veh, idx) => (idx === i ? { ...veh, [field]: v } : veh)));
  };

  const [vinLookupLoading, setVinLookupLoading] = useState(null);
  const [vinLookupError, setVinLookupError] = useState(null);

  const lookupVin = async (i) => {
    const vin = vehicles[i].vin;
    if (!vin || vin.trim().length !== 17) {
      setVinLookupError(i);
      setTimeout(() => setVinLookupError((cur) => (cur === i ? null : cur)), 3000);
      return;
    }
    setVinLookupLoading(i);
    setVinLookupError(null);
    const match = await decodeVin(vin);
    setVinLookupLoading(null);
    if (match) {
      setVehicles((prev) => prev.map((v, idx) => (idx === i ? { ...v, ...match } : v)));
    } else {
      setVinLookupError(i);
      setTimeout(() => setVinLookupError((cur) => (cur === i ? null : cur)), 3000);
    }
  };

  const addVehicle = () => setVehicles((prev) => [...prev, blankVehicle()]);
  const removeVehicle = (i) => {
    setArchivedVehicles((arch) => [...arch, vehicles[i]]);
    setVehicles((prev) => prev.filter((_, idx) => idx !== i));
  };
  const restoreVehicle = (i) => {
    setVehicles((prev) => [...prev, archivedVehicles[i]]);
    setArchivedVehicles((prev) => prev.filter((_, idx) => idx !== i));
  };

  const total = (parseFloat(policyAmount) || 0) + (parseFloat(downPayment) || 0);

  const viewOnly = lockable && !isEditing;

  return (
    <div className="mt-5 pt-5 border-t" style={{ borderColor: "#D8DCE1" }}>
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-bold" style={{ color: COLORS.charcoal }}>
          Drivers, Vehicles &amp; Payment
        </h3>
        {lockable && (
          <button
            onClick={() => setIsEditing((e) => !e)}
            className="text-xs font-semibold"
            style={{ color: COLORS.blue }}
          >
            {isEditing ? "Cancel" : "Edit"}
          </button>
        )}
      </div>

      {viewOnly ? (
        <div className="space-y-4">
          {drivers.map((d, i) => (
            <div key={i} className="border rounded-sm p-3" style={{ borderColor: "#D8DCE1", backgroundColor: COLORS.lightGray }}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-bold" style={{ color: COLORS.charcoal }}>
                  {i + 1}. {`${d.firstName || ""} ${d.lastName || ""}`.trim() || `Driver ${i + 1}`}
                </span>
                <div className="flex items-center gap-2">
                  <span
                    className="text-xs font-semibold px-2 py-0.5 rounded-sm text-white"
                    style={{ backgroundColor: (d.status || "Included") === "Excluded" ? COLORS.red : COLORS.slate }}
                  >
                    {d.status || "Included"}
                  </span>
                  <span className="text-xs font-semibold px-2 py-0.5 rounded-sm text-white" style={{ backgroundColor: COLORS.blue }}>
                    {d.relation || "-"}
                  </span>
                </div>
              </div>
              <div className="grid grid-cols-3 gap-x-4 gap-y-1 text-sm">
                <div>
                  <span className="text-xs block" style={{ color: COLORS.slate }}>Date of Birth</span>
                  {d.dob || "-"}
                </div>
                <div>
                  <span className="text-xs block" style={{ color: COLORS.slate }}>ID Number</span>
                  {d.idNumber || "-"}
                </div>
                <div>
                  <span className="text-xs block" style={{ color: COLORS.slate }}>Sex</span>
                  {d.sex || "-"}
                </div>
                <div>
                  <span className="text-xs block" style={{ color: COLORS.slate }}>Marital Status</span>
                  {d.maritalStatus || "-"}
                </div>
                <div>
                  <span className="text-xs block" style={{ color: COLORS.slate }}>Phone</span>
                  {d.phone || "-"}
                </div>
              </div>
            </div>
          ))}

          <div>
            <span className="text-xs font-bold block mb-2" style={{ color: COLORS.slate }}>VEHICLES</span>
            <div className="space-y-2">
              {vehicles.map((v, i) => (
                <div key={i} className="flex items-center justify-between border rounded-sm px-3 py-2" style={{ borderColor: "#D8DCE1" }}>
                  <span className="text-sm font-semibold" style={{ color: COLORS.charcoal }}>
                    {i + 1}. {(v.year || v.make || v.model) ? [v.year, v.make, v.model].filter(Boolean).join(" ") : `Vehicle ${i + 1}`}
                  </span>
                  <span className="flex items-center gap-3">
                    <span
                      className="text-xs font-semibold px-2 py-0.5 rounded-sm"
                      style={{
                        color: (v.coverage || "Liability Only") === "Liability Only" ? COLORS.red : COLORS.blue,
                        backgroundColor: COLORS.lightGray,
                      }}
                    >
                      {v.coverage || "Liability Only"}
                    </span>
                    <span className="text-xs" style={{ color: COLORS.slate }}>{v.vin || "-"}</span>
                  </span>
                </div>
              ))}
            </div>
          </div>

          {showPayment && (
            <div className="flex items-center justify-between border rounded-sm px-4 py-3" style={{ borderColor: COLORS.blue, backgroundColor: COLORS.lightGray }}>
              <span className="text-sm" style={{ color: COLORS.charcoal }}>
                Policy {formatMoney(policyAmount)} + Down Payment {formatMoney(downPayment)}
              </span>
              <span className="text-sm font-bold" style={{ color: COLORS.blue }}>Total: {formatMoney(total)}</span>
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="mb-5">
            <label className="block text-xs font-semibold mb-2" style={{ color: COLORS.charcoal }}>
              Drivers
            </label>
            <div className="space-y-3">
              {drivers.map((d, i) => (
                <div key={i} className="border rounded-sm p-4" style={{ borderColor: "#D8DCE1", backgroundColor: COLORS.lightGray }}>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-xs font-bold" style={{ color: COLORS.slate }}>
                      DRIVER {i + 1}
                    </span>
                    <button
                      onClick={() => removeDriver(i)}
                      className="text-xs font-semibold"
                      style={{ color: COLORS.red }}
                    >
                      Remove
                    </button>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        First Name
                      </label>
                      <input
                        type="text"
                        value={d.firstName}
                        onChange={(e) => updateDriver(i, "firstName", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Last Name
                      </label>
                      <input
                        type="text"
                        value={d.lastName}
                        onChange={(e) => updateDriver(i, "lastName", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Date of Birth
                      </label>
                      <input
                        type="text"
                        value={d.dob}
                        onChange={(e) => updateDriver(i, "dob", formatDateInput(e.target.value))}
                        placeholder="MM/DD/YYYY"
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        ID Number
                      </label>
                      <input
                        type="text"
                        value={d.idNumber}
                        onChange={(e) => updateDriver(i, "idNumber", e.target.value)}
                        placeholder="Driver's license or ID number"
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Sex
                      </label>
                      <select
                        value={d.sex}
                        onChange={(e) => updateDriver(i, "sex", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      >
                        <option value="">Select</option>
                        <option>Male</option>
                        <option>Female</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Marital Status
                      </label>
                      <select
                        value={d.maritalStatus}
                        onChange={(e) => updateDriver(i, "maritalStatus", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      >
                        <option value="">Select</option>
                        <option>Single</option>
                        <option>Married</option>
                        <option>Divorced</option>
                        <option>Widowed</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Phone <span className="font-normal" style={{ color: COLORS.slate }}>(optional)</span>
                      </label>
                      <input
                        type="text"
                        value={d.phone || ""}
                        onChange={(e) => updateDriver(i, "phone", formatPhoneInput(e.target.value))}
                        placeholder="Phone number"
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Relation to Driver
                      </label>
                      <select
                        value={d.relation}
                        onChange={(e) => updateDriver(i, "relation", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      >
                        <option value="">Select</option>
                        <option>Self</option>
                        <option>Spouse</option>
                        <option>Child</option>
                        <option>Relative</option>
                        <option>Other</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>
                        Included / Excluded
                      </label>
                      <select
                        value={d.status || "Included"}
                        onChange={(e) => updateDriver(i, "status", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      >
                        <option>Included</option>
                        <option>Excluded</option>
                      </select>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addDriver} className="text-xs font-semibold mt-3" style={{ color: COLORS.blue }}>
              + Add another driver
            </button>
            {archivedDrivers.length > 0 && (
              <div className="mt-2">
                <button
                  onClick={() => setShowArchivedDrivers((s) => !s)}
                  className="text-xs font-semibold"
                  style={{ color: COLORS.slate }}
                >
                  {showArchivedDrivers ? "Hide" : "Show"} removed drivers ({archivedDrivers.length})
                </button>
                {showArchivedDrivers && (
                  <div className="mt-2 space-y-2">
                    {archivedDrivers.map((d, i) => (
                      <div key={i} className="flex items-center justify-between border rounded-sm px-3 py-2" style={{ borderColor: "#D8DCE1", backgroundColor: COLORS.lightGray }}>
                        <span className="text-sm" style={{ color: COLORS.charcoal }}>
                          {`${d.firstName || ""} ${d.lastName || ""}`.trim() || "Unnamed driver"} {d.relation && `(${d.relation})`}
                        </span>
                        <button onClick={() => restoreDriver(i)} className="text-xs font-semibold" style={{ color: COLORS.blue }}>
                          Restore
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="mb-5">
            <label className="block text-xs font-semibold mb-2" style={{ color: COLORS.charcoal }}>
              Vehicles
            </label>
            <div className="space-y-3">
              {vehicles.map((v, i) => (
                <div key={i} className="border rounded-sm p-4" style={{ borderColor: "#D8DCE1", backgroundColor: COLORS.lightGray }}>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-xs font-bold" style={{ color: COLORS.slate }}>
                      VEHICLE {i + 1}
                    </span>
                    <button
                      onClick={() => removeVehicle(i)}
                      className="text-xs font-semibold"
                      style={{ color: COLORS.red }}
                    >
                      Remove
                    </button>
                  </div>
                  <div className="flex gap-2 mb-1">
                    <input
                      type="text"
                      value={v.vin}
                      onChange={(e) => updateVehicleField(i, "vin", e.target.value)}
                      onBlur={() => v.vin && v.vin.trim() && lookupVin(i)}
                      placeholder="VIN"
                      className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                      style={{ borderColor: vinLookupError === i ? COLORS.red : "#D8DCE1", color: COLORS.charcoal }}
                    />
                    <button
                      onClick={() => lookupVin(i)}
                      disabled={vinLookupLoading === i}
                      className="px-3 text-xs font-semibold rounded-sm border whitespace-nowrap"
                      style={{ color: COLORS.blue, borderColor: "#D8DCE1", backgroundColor: "white", opacity: vinLookupLoading === i ? 0.6 : 1 }}
                    >
                      {vinLookupLoading === i ? "Looking up..." : "Look Up"}
                    </button>
                  </div>
                  {vinLookupError === i && (
                    <p className="text-xs mb-2" style={{ color: COLORS.red }}>
                      Couldn't find that VIN. Double-check it's entered correctly (17 characters), or fill in Year/Make/Model manually.
                    </p>
                  )}
                  <div className="grid grid-cols-3 gap-3 mt-3">
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Year</label>
                      <input
                        type="text"
                        value={v.year}
                        onChange={(e) => updateVehicleField(i, "year", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Make</label>
                      <input
                        type="text"
                        value={v.make}
                        onChange={(e) => updateVehicleField(i, "make", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Model</label>
                      <input
                        type="text"
                        value={v.model}
                        onChange={(e) => updateVehicleField(i, "model", e.target.value)}
                        className="w-full border rounded-sm px-3 py-2 text-sm outline-none bg-white"
                        style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                      />
                    </div>
                  </div>
                  <div className="mt-3">
                    <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Coverage</label>
                    <div className="flex gap-4">
                      {["Liability Only", "Full Coverage"].map((option) => (
                        <label key={option} className="flex items-center gap-2 text-sm cursor-pointer" style={{ color: COLORS.charcoal }}>
                          <input
                            type="checkbox"
                            checked={(v.coverage || "Liability Only") === option}
                            onChange={() => updateVehicleField(i, "coverage", option)}
                            className="h-4 w-4"
                            style={{ accentColor: COLORS.blue }}
                          />
                          {option}
                        </label>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addVehicle} className="text-xs font-semibold mt-3" style={{ color: COLORS.blue }}>
              + Add another VIN
            </button>
            <p className="text-xs mt-2" style={{ color: COLORS.slate }}>
              Enter a VIN and click Look Up (or tab out of the field) to pull the year, make, and model automatically. Fields stay editable if anything needs correcting.
            </p>
            {archivedVehicles.length > 0 && (
              <div className="mt-2">
                <button
                  onClick={() => setShowArchivedVehicles((s) => !s)}
                  className="text-xs font-semibold"
                  style={{ color: COLORS.slate }}
                >
                  {showArchivedVehicles ? "Hide" : "Show"} removed vehicles ({archivedVehicles.length})
                </button>
                {showArchivedVehicles && (
                  <div className="mt-2 space-y-2">
                    {archivedVehicles.map((v, i) => (
                      <div key={i} className="flex items-center justify-between border rounded-sm px-3 py-2" style={{ borderColor: "#D8DCE1", backgroundColor: COLORS.lightGray }}>
                        <span className="text-sm" style={{ color: COLORS.charcoal }}>
                          {(v.year || v.make || v.model) ? [v.year, v.make, v.model].filter(Boolean).join(" ") : "Unnamed vehicle"} {v.vin && `- ${v.vin}`}
                        </span>
                        <button onClick={() => restoreVehicle(i)} className="text-xs font-semibold" style={{ color: COLORS.blue }}>
                          Restore
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {showPayment && (
            <div>
              <label className="block text-xs font-semibold mb-2" style={{ color: COLORS.charcoal }}>
                Payment
              </label>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs mb-1" style={{ color: COLORS.slate }}>Policy Amount</label>
                  <MoneyInput value={policyAmount} onChange={setPolicyAmount} />
                </div>
                <div>
                  <label className="block text-xs mb-1" style={{ color: COLORS.slate }}>Down Payment</label>
                  <MoneyInput value={downPayment} onChange={setDownPayment} />
                </div>
              </div>
              <div className="mt-3 flex items-center justify-between border rounded-sm px-4 py-3" style={{ borderColor: COLORS.blue, backgroundColor: COLORS.lightGray }}>
                <span className="text-sm font-semibold" style={{ color: COLORS.charcoal }}>Total Initial Payment</span>
                <span className="text-lg font-bold" style={{ color: COLORS.blue }}>{formatMoney(total)}</span>
              </div>
            </div>
          )}

          <button
            onClick={() => {
              const missing = [];
              drivers.forEach((d, idx) => {
                if (isBlank(d.firstName)) missing.push(`Driver ${idx + 1} First Name`);
                if (isBlank(d.lastName)) missing.push(`Driver ${idx + 1} Last Name`);
                if (isBlank(d.dob)) missing.push(`Driver ${idx + 1} Date of Birth`);
                if (isBlank(d.idNumber)) missing.push(`Driver ${idx + 1} ID Number`);
              });
              vehicles.forEach((v, idx) => {
                if (isBlank(v.vin)) missing.push(`Vehicle ${idx + 1} VIN`);
              });
              if (missing.length > 0) {
                setValidationError(`Please fill in: ${missing.join(", ")}.`);
                return;
              }
              setValidationError("");
              if (onSaveDetails) onSaveDetails({ drivers, vehicles, policyAmount, downPayment, total });
              if (lockable) setIsEditing(false);
            }}
            className="mt-5 px-5 py-2 text-white text-sm font-semibold rounded-sm"
            style={{ backgroundColor: COLORS.blue }}
          >
            SAVE DRIVER &amp; VEHICLE INFO
          </button>
          {validationError && (
            <p className="text-xs font-semibold mt-2" style={{ color: COLORS.red }}>{validationError}</p>
          )}
        </>
      )}
    </div>
  );
}

