              <div className="col-span-2">
                <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Street Address</label>
                <input
                  type="text"
                  value={customerInfo.address}
                  onChange={(e) => updateCustomerField("address", e.target.value)}
                  className="w-full border rounded-sm px-3 py-2 text-sm outline-none"
                  style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>City</label>
                <input
