function TagListEditor({ initialTags }) {
  const [tags, setTags] = useState(initialTags);
  const [newTag, setNewTag] = useState("");

  const addTag = () => {
    if (!newTag.trim()) return;
    setTags((prev) => [...prev, toTitleCase(newTag.trim())]);
    setNewTag("");
  };

  const removeTag = (i) => setTags((prev) => prev.filter((_, idx) => idx !== i));

  return (
    <div className="bg-white border rounded-sm p-5" style={{ borderColor: "#D8DCE1" }}>
      <div className="flex flex-wrap gap-2 mb-4">
        {tags.map((t, i) => (
          <span
            key={t}
            className="flex items-center gap-2 px-3 py-1.5 text-sm rounded-sm"
            style={{ backgroundColor: COLORS.lightGray, color: COLORS.charcoal }}
          >
            {t}
            <button onClick={() => removeTag(i)} style={{ color: COLORS.red }} className="font-bold">
              {"\u00d7"}
            </button>
          </span>
        ))}
      </div>
      <div className="flex gap-2">
        <input
          type="text"
          value={newTag}
          onChange={(e) => setNewTag(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addTag()}
          placeholder="Add new option"
          className="w-full border rounded-sm px-3 py-2 text-sm outline-none"
          style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
        />
        <button onClick={addTag} className="px-4 py-2 text-white text-sm font-semibold rounded-sm whitespace-nowrap" style={{ backgroundColor: COLORS.blue }}>
          + ADD
        </button>
      </div>
    </div>
  );
}

function EmployeesPanel({ employees, setEmployees }) {
  const [showAddEmployee, setShowAddEmployee] = useState(false);
  const [resetSentFor, setResetSentFor] = useState(null);

  const updateRole = async (i, role) => {
    const target = employees[i];
    if (!target) return;
    setEmployees((prev) => prev.map((e, idx) => (idx === i ? { ...e, role } : e)));
    await updateEmployeeById(target.id, { role });
  };

  const toggleStatus = async (i) => {
    const target = employees[i];
    if (!target) return;
    const newStatus = target.status === "Active" ? "Deactivated" : "Active";
    setEmployees((prev) => prev.map((e, idx) => (idx === i ? { ...e, status: newStatus } : e)));
    await updateEmployeeById(target.id, { status: newStatus });
  };

  const resetPassword = async (i) => {
    setResetSentFor(i);
    await supabase.auth.resetPasswordForEmail(employees[i].email);
    setTimeout(() => setResetSentFor((cur) => (cur === i ? null : cur)), 2500);
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-bold" style={{ color: COLORS.charcoal }}>Manage Employees</h2>
        <button onClick={() => setShowAddEmployee((s) => !s)} className="text-sm font-semibold" style={{ color: COLORS.blue }}>
          How do I add a new employee?
        </button>
      </div>
      {showAddEmployee && (
        <div className="bg-white border rounded-sm p-5 mb-4" style={{ borderColor: "#D8DCE1" }}>
          <p className="text-sm font-semibold mb-2" style={{ color: COLORS.charcoal }}>
            Adding a new employee takes two steps in Supabase (this page can only edit people who already have a login):
          </p>
          <ol className="text-sm list-decimal list-inside space-y-1 mb-3" style={{ color: COLORS.charcoal }}>
            <li>Supabase &rarr; Authentication &rarr; Users &rarr; Add user (their real email + a temporary password)</li>
            <li>Supabase &rarr; Table Editor &rarr; employees &rarr; Insert row (paste their new user ID, name, office, and role)</li>
          </ol>
          <p className="text-xs mb-3" style={{ color: COLORS.slate }}>
            This is a one-time security step - creating logins requires access this app intentionally doesn't have client-side. Once they're in the employees table, they'll show up below and you can manage their role/office/status right here.
          </p>
          <button onClick={() => setShowAddEmployee(false)} className="text-sm font-semibold" style={{ color: COLORS.slate }}>
            Close
          </button>
        </div>
      )}
      <div className="bg-white border rounded-sm overflow-hidden" style={{ borderColor: "#D8DCE1" }}>
        <table className="w-full text-sm">
          <thead>
            <tr style={{ backgroundColor: COLORS.slate }}>
              {["Name", "Email", "Office", "Access Level", "Status", ""].map((h) => (
                <th key={h} className="text-left px-4 py-3 text-white font-bold">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {employees.map((e, i) => (
              <tr key={e.email} style={{ backgroundColor: i % 2 ? COLORS.lightGray : "white" }}>
                <td className="px-4 py-3 font-medium" style={{ color: COLORS.charcoal }}>{e.name}</td>
                <td className="px-4 py-3" style={{ color: COLORS.charcoal }}>{e.email}</td>
                <td className="px-4 py-3" style={{ color: COLORS.charcoal }}>{e.office}</td>
                <td className="px-4 py-3">
                  <select
                    value={e.role}
                    onChange={(ev) => updateRole(i, ev.target.value)}
                    className="border rounded-sm px-2 py-1 text-sm outline-none"
                    style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
                  >
                    <option>Admin</option>
                    <option>Employee</option>
                  </select>
                </td>
                <td className="px-4 py-3">
                  <span
                    className="text-xs font-semibold px-2 py-1 rounded-sm"
                    style={
                      e.status === "Active"
                        ? { color: COLORS.blue, backgroundColor: COLORS.lightGray }
                        : { color: COLORS.red, backgroundColor: COLORS.lightGray }
                    }
                  >
                    {e.status}
                  </span>
                </td>
                <td className="px-4 py-3 text-right whitespace-nowrap">
                  <button
                    onClick={() => resetPassword(i)}
                    className="text-xs font-semibold mr-3"
                    style={{ color: resetSentFor === i ? COLORS.slate : COLORS.blue }}
                  >
                    {resetSentFor === i ? "Reset email sent" : "Reset Password"}
                  </button>
                  <button onClick={() => toggleStatus(i)} className="text-xs font-semibold" style={{ color: COLORS.red }}>
                    {e.status === "Active" ? "Deactivate" : "Reactivate"}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

