function DataManagementPanel({ customers }) {
  const [message, setMessage] = useState("");

  const exportCustomers = () => {
    if (!customers || customers.length === 0) {
      setMessage("No customers to export yet.");
      return;
    }
    const columns = ["name", "phone", "email", "address", "city", "state", "zip", "office", "carrier", "policyNumber"];
    const rows = [columns.join(",")];
    customers.forEach((c) => {
      rows.push(columns.map((col) => `"${(c[col] || "").toString().replace(/"/g, '""')}"`).join(","));
    });
    const csv = rows.join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "customers.csv";
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <h2 className="text-lg font-bold mb-4" style={{ color: COLORS.charcoal }}>Data Management</h2>
      {message && (
        <p className="text-xs font-semibold mb-3" style={{ color: COLORS.blue }}>{message}</p>
      )}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-white border rounded-sm p-5" style={{ borderColor: "#D8DCE1" }}>
          <h3 className="text-sm font-bold mb-2" style={{ color: COLORS.charcoal }}>Export Customer Data</h3>
          <p className="text-xs mb-4" style={{ color: COLORS.slate }}>Download all customers as a spreadsheet (CSV).</p>
          <button onClick={exportCustomers} className="px-4 py-2 text-white text-xs font-semibold rounded-sm" style={{ backgroundColor: COLORS.blue }}>
            EXPORT DATA
          </button>
        </div>
        <div className="bg-white border rounded-sm p-5" style={{ borderColor: "#D8DCE1" }}>
          <h3 className="text-sm font-bold mb-2" style={{ color: COLORS.charcoal }}>Backups</h3>
          <p className="text-xs mb-4" style={{ color: COLORS.slate }}>Automatic backups are managed by Supabase directly, not this app.</p>
          <button
            onClick={() => setMessage("Backups run through Supabase (Project \u2192 Database \u2192 Backups), not from this page.")}
            className="px-4 py-2 text-white text-xs font-semibold rounded-sm"
            style={{ backgroundColor: COLORS.blue }}
          >
            BACKUP NOW
          </button>
        </div>
        <div className="bg-white border rounded-sm p-5" style={{ borderColor: "#D8DCE1" }}>
          <h3 className="text-sm font-bold mb-2" style={{ color: COLORS.charcoal }}>Restore</h3>
          <p className="text-xs mb-4" style={{ color: COLORS.slate }}>Restoring from a backup point is also done in Supabase.</p>
          <button
            onClick={() => setMessage("Backup history and restore points live in your Supabase project dashboard.")}
            className="px-4 py-2 text-white text-xs font-semibold rounded-sm"
            style={{ backgroundColor: COLORS.blue }}
          >
            VIEW BACKUPS
          </button>
        </div>
      </div>
    </div>
  );
}

function DuplicateReviewPanel() {
  const [pairs, setPairs] = useState(duplicatePairsSample);
  const [message, setMessage] = useState("");

  const resolve = (i, action) => {
    const pair = pairs[i];
    setPairs((prev) => prev.filter((_, idx) => idx !== i));
    setMessage(
      action === "merge"
        ? `Flagged this pair for merging. To finish it, open each profile and confirm which one to keep.`
        : `Dismissed - ${pair.nameA} and ${pair.nameB} won't be flagged as duplicates anymore.`
    );
  };

  return (
    <div>
      <h2 className="text-lg font-bold mb-4" style={{ color: COLORS.charcoal }}>Duplicate Customer Review</h2>
      {message && (
        <p className="text-xs font-semibold mb-3" style={{ color: COLORS.blue }}>{message}</p>
      )}
      <div className="bg-white border rounded-sm overflow-hidden" style={{ borderColor: "#D8DCE1" }}>
        {pairs.map((d, i) => (
          <div key={i} className="p-4 flex items-center justify-between" style={{ backgroundColor: i % 2 ? COLORS.lightGray : "white" }}>
            <div className="text-sm" style={{ color: COLORS.charcoal }}>
              <span className="font-semibold">{d.nameA}</span> ({d.officeA}) and{" "}
              <span className="font-semibold">{d.nameB}</span> ({d.officeB})
              <div className="text-xs mt-0.5" style={{ color: COLORS.slate }}>Flagged: {d.matchedOn}</div>
            </div>
            <div className="flex gap-3 whitespace-nowrap">
              <button onClick={() => resolve(i, "merge")} className="text-xs font-semibold" style={{ color: COLORS.blue }}>Merge</button>
              <button onClick={() => resolve(i, "ignore")} className="text-xs font-semibold" style={{ color: COLORS.slate }}>Ignore</button>
            </div>
          </div>
        ))}
        {pairs.length === 0 && (
          <p className="text-sm text-center py-6" style={{ color: COLORS.slate }}>No flagged duplicates right now.</p>
        )}
      </div>
      <p className="text-xs mt-3" style={{ color: COLORS.slate }}>
        Customers are flagged here when their name is a close match and they share a phone number, email, or address with another profile.
      </p>
    </div>
  );
}

