function AdminPage({ customers, employees, setEmployees, carriers, setCarriers }) {
  const [section, setSection] = useState("Employees");

  const addCarrier = async (name) => {
    if (!name.trim()) return;
    const saved = await insertCarrier(toTitleCase(name.trim()));
    if (saved) setCarriers((prev) => [...prev, saved]);
  };

  const updateCarrierUrl = async (i, url) => {
    const target = carriers[i];
    if (!target) return;
    setCarriers((prev) => prev.map((c, idx) => (idx === i ? { ...c, portalUrl: url } : c)));
    const saved = await updateCarrierById(target.id, url);
    if (saved) setCarriers((prev) => prev.map((c) => (c.id === saved.id ? saved : c)));
  };

  const removeCarrier = async (i) => {
    const target = carriers[i];
    if (!target) return;
    const ok = await deleteCarrierById(target.id);
    if (ok) setCarriers((prev) => prev.filter((_, idx) => idx !== i));
  };

  return (
    <div className="max-w-6xl mx-auto px-6 py-8 flex gap-6">
      <div className="w-56 shrink-0">
        <div className="bg-white border rounded-sm overflow-hidden" style={{ borderColor: "#D8DCE1" }}>
          {ADMIN_SECTIONS.map((s) => {
            const active = s === section;
            return (
              <button
                key={s}
                onClick={() => setSection(s)}
                className="w-full text-left px-4 py-3 text-sm font-medium"
                style={{
                  color: active ? "white" : COLORS.charcoal,
                  backgroundColor: active ? COLORS.darkBlue : "white",
                }}
              >
                {s}
              </button>
            );
          })}
        </div>
      </div>
      <div className="flex-1">
        {section === "Employees" && <EmployeesPanel employees={employees} setEmployees={setEmployees} />}
        {section === "Offices" && <OfficesPanel />}
        {section === "Insurance Companies" && (
          <InsuranceCompaniesPanel carriers={carriers} onAdd={addCarrier} onRemove={removeCarrier} />
        )}
        {section === "Carrier Portal Links" && (
          <CarrierPortalLinksPanel carriers={carriers} onUpdateUrl={updateCarrierUrl} onRemove={removeCarrier} />
        )}
        {section === "Policy Types" && (
          <div>
            <h2 className="text-lg font-bold mb-4" style={{ color: COLORS.charcoal }}>Policy Types</h2>
            <TagListEditor initialTags={["Personal Auto", "Commercial Auto", "General Liability", "Homeowners", "Renters", "Motorcycle", "Other"]} />
          </div>
        )}
        {section === "Document Categories" && (
          <div>
            <h2 className="text-lg font-bold mb-4" style={{ color: COLORS.charcoal }}>Document Categories</h2>
            <TagListEditor initialTags={["ID", "Declaration Page", "Application", "Insurance Card", "Signed Form"]} />
          </div>
        )}
        {section === "Audit Log" && <AuditLogPanel customers={customers} />}
        {section === "Data Management" && <DataManagementPanel customers={customers} />}
        {section === "Duplicate Customer Review" && <DuplicateReviewPanel />}
        {section === "System Settings" && <SystemSettingsPanel />}
      </div>
    </div>
  );
}

