function EmployeeLoginPage({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [sessionOffice, setSessionOffice] = useState("Rampart Office");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    setError("");
    setLoading(true);

    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email: email.trim(),
      password,
    });

    if (authError) {
      setLoading(false);
      setError("Email or password is incorrect.");
      return;
    }

    const { data: profile, error: profileError } = await supabase
      .from("employees")
      .select("*")
      .eq("id", authData.user.id)
      .single();

    setLoading(false);

    if (profileError || !profile) {
      setError("No employee profile found for this login. Contact an admin.");
      await supabase.auth.signOut();
      return;
    }
    if (profile.status === "Deactivated") {
      setError("This account has been deactivated. Contact an admin.");
      await supabase.auth.signOut();
      return;
    }

    onLogin({ ...profile, sessionOffice });
  };

  return (
    <div className="min-h-screen flex items-center justify-center" style={{ backgroundColor: COLORS.lightGray }}>
      <div className="max-w-sm w-full px-6 text-center">
        <img src={FULL_LOGO_SRC} alt="Popular Multiservice" className="h-16 w-auto mx-auto mb-6" />
        <div className="bg-white border rounded-sm p-8 text-left" style={{ borderColor: "#D8DCE1" }}>
          <div className="flex justify-center mb-3">
            <Lock size={28} color={COLORS.slate} />
          </div>
          <h2 className="text-lg font-bold mb-1 text-center" style={{ color: COLORS.charcoal }}>Policy Hub Login</h2>
          <p className="text-xs mb-4 text-center" style={{ color: COLORS.slate }}>
            Sign in with your work email. Changes you make are recorded under your name.
          </p>
          <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => {
              setEmail(e.target.value);
              setError("");
            }}
            className="w-full border rounded-sm px-3 py-2 text-sm outline-none mb-3"
            style={{ borderColor: error ? COLORS.red : "#D8DCE1", color: COLORS.charcoal }}
            placeholder="you@popularmultiservice.com"
          />
          <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => {
              setPassword(e.target.value);
              setError("");
            }}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            className="w-full border rounded-sm px-3 py-2 text-sm outline-none mb-3"
            style={{ borderColor: error ? COLORS.red : "#D8DCE1", color: COLORS.charcoal }}
            placeholder="Password"
          />
          <label className="block text-xs font-semibold mb-1" style={{ color: COLORS.charcoal }}>Working From</label>
          <select
            value={sessionOffice}
            onChange={(e) => setSessionOffice(e.target.value)}
            className="w-full border rounded-sm px-3 py-2 text-sm outline-none"
            style={{ borderColor: "#D8DCE1", color: COLORS.charcoal }}
          >
            <option>Rampart Office</option>
            <option>Harwin Office</option>
          </select>
          {error && (
            <p className="text-xs mt-2" style={{ color: COLORS.red }}>{error}</p>
          )}
          <button
            onClick={submit}
            disabled={loading}
            className="w-full mt-4 px-5 py-2 text-white text-sm font-semibold rounded-sm"
            style={{ backgroundColor: COLORS.blue, opacity: loading ? 0.6 : 1 }}
          >
            {loading ? "LOGGING IN..." : "LOG IN"}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [authStep, setAuthStep] = useState("login");
  const [employeeName, setEmployeeName] = useState("");
  const [employeeProfile, setEmployeeProfile] = useState(null);
  const [page, setPage] = useState("Dashboard");
  const [customers, setCustomers] = useState([]);
  const [customersLoading, setCustomersLoading] = useState(true);
  const [selectedCustomerName, setSelectedCustomerName] = useState(null);
  const selectedCustomer = customers.find((c) => c.name === selectedCustomerName) || null;
  const [selectedQuote, setSelectedQuote] = useState(null);
  const [isNewQuote, setIsNewQuote] = useState(false);
  const [recentlyViewedNames, setRecentlyViewedNames] = useState(() => {
    try {
      const stored = localStorage.getItem("policyhub_recently_viewed");
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  });

  // Wire the browser's Back/Forward buttons to in-app navigation instead of
  // leaving the site entirely. Every navigational change pushes a history
  // entry; popstate restores state without pushing again (avoids a loop).
  useEffect(() => {
    window.history.replaceState({ page: "Dashboard", selectedCustomerName: null, selectedQuote: null, isNewQuote: false }, "");
    const handlePopState = (e) => {
      const s = e.state || { page: "Dashboard", selectedCustomerName: null, selectedQuote: null, isNewQuote: false };
      setPage(s.page);
      setSelectedCustomerName(s.selectedCustomerName || null);
      setSelectedQuote(s.selectedQuote || null);
      setIsNewQuote(!!s.isNewQuote);
    };
    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, []);

  const pushNav = (updates) => {
    const next = {
      page: "page" in updates ? updates.page : page,
      selectedCustomerName: "selectedCustomerName" in updates ? updates.selectedCustomerName : selectedCustomerName,
      selectedQuote: "selectedQuote" in updates ? updates.selectedQuote : selectedQuote,
      isNewQuote: "isNewQuote" in updates ? updates.isNewQuote : isNewQuote,
    };
    if ("page" in updates) setPage(next.page);
    if ("selectedCustomerName" in updates) setSelectedCustomerName(next.selectedCustomerName);
    if ("selectedQuote" in updates) setSelectedQuote(next.selectedQuote);
    if ("isNewQuote" in updates) setIsNewQuote(next.isNewQuote);
    window.history.pushState(next, "");
  };
  const [adminUnlocked, setAdminUnlocked] = useState(false);
  const [quotes, setQuotes] = useState([]);
  const [quotesLoading, setQuotesLoading] = useState(true);
  const [employees, setEmployees] = useState([]);
  const [carriers, setCarriers] = useState([]);
  const carrierPortalUrls = Object.fromEntries(carriers.map((c) => [c.name, c.portalUrl]));

  useEffect(() => {
    if (authStep !== "app") return;
    setCustomersLoading(true);
    fetchCustomers().then((data) => {
      setCustomers(data);
      setCustomersLoading(false);
    });
    setQuotesLoading(true);
    fetchQuotes().then((data) => {
      setQuotes(data);
      setQuotesLoading(false);
    });
    fetchCarriers().then(setCarriers);
    fetchEmployees().then(setEmployees);
  }, [authStep]);

  const updateCustomerRecord = async (customerName, patch) => {
    const target = customers.find((c) => c.name === customerName);
    if (!target) return;
    // Optimistic local update so the UI feels instant
    setCustomers((prev) => prev.map((c) => (c.id === target.id ? { ...c, ...patch } : c)));
    const saved = await updateCustomerById(target.id, patch);
    if (saved) {
      // Merge only the fields this call actually patched, rather than replacing
      // the whole row with Supabase's response. Two saves can fire back-to-back
      // for the same customer (e.g. driver info + the activity log entry it
      // creates) - replacing the whole row here could clobber whichever one's
      // response comes back second with a stale snapshot of the other's fields.
      setCustomers((prev) => prev.map((c) => (c.id === target.id ? { ...c, ...patch } : c)));
    }
  };

  const markCustomerActive = (name) => {
    if (!name) return;
    updateCustomerRecord(name, { active: true });
  };

  const openCustomer = (customer) => {
    setRecentlyViewedNames((prev) => {
      const next = [customer.name, ...prev.filter((n) => n !== customer.name)].slice(0, 10);
      try {
        localStorage.setItem("policyhub_recently_viewed", JSON.stringify(next));
      } catch {}
      return next;
    });
    pushNav({ page: "Customer", selectedCustomerName: customer.name });
  };

  const openQuote = (quote) => {
    pushNav({ page: "QuoteDetail", selectedQuote: quote, isNewQuote: false });
  };

  const addNewQuote = () => {
    pushNav({ page: "QuoteDetail", selectedQuote: null, isNewQuote: true });
  };

  const saveQuoteRecord = async (record, originalQuoteNumber, quoteId) => {
    if (quoteId) {
      const saved = await updateQuoteById(quoteId, record);
      if (saved) setQuotes((prev) => prev.map((q) => (q.id === quoteId ? saved : q)));
      return saved;
    }
    const withCreator = { ...record, createdBy: employeeProfile?.id || null };
    const saved = await insertQuote(withCreator);
    if (saved) setQuotes((prev) => [saved, ...prev]);
    return saved;
  };

  const addRequoteToCustomer = (customerName, record) => {
    const target = customers.find((c) => c.name === customerName);
    if (!target) return;
    updateCustomerRecord(customerName, { requotes: [record, ...(target.requotes || [])] });
    markCustomerActive(customerName);
  };

  const addCustomer = async (record) => {
    const withCreator = { ...record, createdBy: employeeProfile?.id || null, active: true };
    const saved = await insertCustomer(withCreator);
    if (!saved) return null;
    setCustomers((prev) => [...prev, saved]);
    return saved;
  };

  const deleteCustomer = async (customer) => {
    const ok = await deleteCustomerById(customer.id);
    if (!ok) return;
    setCustomers((prev) => prev.filter((c) => c.id !== customer.id));
    pushNav({ page: "CustomersList" });
  };

  const deleteQuote = async (quote) => {
    const ok = await deleteQuoteById(quote.id);
    if (!ok) return;
    setQuotes((prev) => prev.filter((q) => q.id !== quote.id));
    pushNav({ page: "QuotesList" });
  };

  const acceptQuote = async (quote) => {
    let targetCustomer = findDuplicateCustomer(customers, quote.driverName, quote.phone);
    if (!targetCustomer) {
      const newCustomerData = {
        name: quote.driverName,
        phone: quote.phone || "",
        email: quote.email || "",
        address: quote.address || "",
        city: quote.city || "",
        state: quote.state || "",
        zip: quote.zip || "",
        office: quote.office || "Rampart Office",
        carrier: quote.carrier,
        policyType: quote.policyType || "Personal Auto",
        insuredName: quote.insuredName || "",
        otherDetails: quote.otherDetails || "",
        policyNumber: "",
        needsPolicyNumber: true,
        drivers:
          quote.drivers && quote.drivers.length
            ? quote.drivers.map((d) => ({ name: `${d.firstName || ""} ${d.lastName || ""}`.trim(), relation: d.relation || "Self" }))
            : [{ name: quote.driverName, relation: "Self" }],
        driverDetails: quote.drivers || [],
        vehicles: quote.vehicles || [],
        policyAmount: quote.policyAmount || "",
        downPayment: quote.downPayment || "",
      };
      targetCustomer = await addCustomer(newCustomerData);
      if (!targetCustomer) return;
    } else {
      markCustomerActive(targetCustomer.name);
    }
    if (quote.id) await deleteQuoteById(quote.id);
    setQuotes((prev) => prev.filter((q) => q.quoteNumber !== quote.quoteNumber));
    openCustomer(targetCustomer);
  };

  const handleNavigate = (item) => {
    if (item === "Customers") {
      pushNav({ page: "CustomersList" });
    } else if (item === "Quotes") {
      pushNav({ page: "QuotesList" });
    } else {
      pushNav({ page: item });
    }
  };

  const activeNav =
    page === "Customer" || page === "CustomersList" || page === "AddCustomer"
      ? "Customers"
      : page === "QuotesList" || page === "QuoteDetail"
      ? "Quotes"
      : page;

  if (authStep === "login") {
    return (
      <EmployeeLoginPage
        onLogin={(profile) => {
          setEmployeeName(profile.name);
          setEmployeeProfile(profile);
          setAuthStep("app");
        }}
      />
    );
  }

  return (
    <div className="min-h-screen" style={{ backgroundColor: COLORS.lightGray }}>
      <TopHeader
        activePage={activeNav}
        onNavigate={handleNavigate}
        employeeName={employeeName}
        onSwitchUser={async () => {
          await supabase.auth.signOut();
          setEmployeeName("");
          setEmployeeProfile(null);
          setAuthStep("login");
        }}
      />
      {customersLoading && (page === "Dashboard" || page === "CustomersList") && (
        <p className="text-center text-sm py-3" style={{ color: COLORS.slate }}>Loading customers...</p>
      )}
      {quotesLoading && (page === "Dashboard" || page === "QuotesList") && (
        <p className="text-center text-sm py-3" style={{ color: COLORS.slate }}>Loading quotes...</p>
      )}
      {page === "Dashboard" && (
        <DashboardPage
          onOpenCustomer={openCustomer}
          onOpenQuote={openQuote}
          onAddNewCustomer={() => pushNav({ page: "AddCustomer" })}
          onAddNewQuote={addNewQuote}
          onGoToQuotes={() => pushNav({ page: "QuotesList" })}
          quotes={quotes}
          customers={customers}
          recentlyViewedNames={recentlyViewedNames}
          onPortalOpen={markCustomerActive}
          carrierPortalUrls={carrierPortalUrls}
        />
      )}
      {page === "CustomersList" && (
        <CustomersListPage
          onOpenCustomer={openCustomer}
          onAddNewCustomer={() => pushNav({ page: "AddCustomer" })}
          customers={customers}
          onPortalOpen={markCustomerActive}
          carrierPortalUrls={carrierPortalUrls}
        />
      )}
      {page === "AddCustomer" && (
        <AddCustomerPage
          onBack={() => pushNav({ page: "CustomersList" })}
          customers={customers}
          onAddCustomer={addCustomer}
          onOpenCustomer={openCustomer}
          defaultOffice={employeeProfile?.sessionOffice}
          carrierPortalUrls={carrierPortalUrls}
        />
      )}
      {page === "Customer" && selectedCustomer && (
        <CustomerProfilePage
          customer={selectedCustomer}
          onPortalOpen={markCustomerActive}
          employeeName={employeeName}
          onDeleteCustomer={deleteCustomer}
          onUpdateCustomer={updateCustomerRecord}
          carrierPortalUrls={carrierPortalUrls}
          employees={employees}
        />
      )}
      {page === "QuotesList" && (
        <QuotesListPage
          onOpenQuote={openQuote}
          onAddNewQuote={addNewQuote}
          quotes={quotes}
          onAcceptQuote={acceptQuote}
          onPortalOpen={markCustomerActive}
          carrierPortalUrls={carrierPortalUrls}
        />
      )}
      {page === "QuoteDetail" && (
        <QuoteDetailPage
          quote={selectedQuote}
          isNew={isNewQuote}
          onBack={() => pushNav({ page: "QuotesList" })}
          onSaveQuote={saveQuoteRecord}
          onAddRequoteToCustomer={addRequoteToCustomer}
          customers={customers}
          employeeName={employeeName}
          onDeleteQuote={deleteQuote}
          defaultOffice={employeeProfile?.sessionOffice}
          carrierPortalUrls={carrierPortalUrls}
        />
      )}
      {page === "Admin" && !adminUnlocked && <AdminGatePage onUnlock={() => setAdminUnlocked(true)} />}
      {page === "Admin" && adminUnlocked && (
        <AdminPage
          customers={customers}
          employees={employees}
          setEmployees={setEmployees}
          carriers={carriers}
          setCarriers={setCarriers}
        />
      )}
      {page === "Policies" && (
        <PoliciesListPage onOpenCustomer={openCustomer} customers={customers} onPortalOpen={markCustomerActive} carrierPortalUrls={carrierPortalUrls} />
      )}
    </div>
  );
}
